<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/mail_service.php';require_once dirname(__DIR__).'/private/mail_engine.php';require_once dirname(__DIR__).'/private/ui.php';
$id=(int)($_GET['id']??0);$folder=(string)($_GET['folder']??'INBOX');$back='mail.php?folder='.rawurlencode($folder).($id?'&id='.$id:'');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');
 if($action==='sync'){$r=gszMailSync($pdo,gszMailRemote($config),$folder,(int)$config['mail_sync_limit']);$_SESSION['app_notice']='Synchronisiert: '.$r['created'].' neue Nachrichten.'.($r['limited']?' Weitere Nachrichten vorhanden: erneut synchronisieren.':'');}
 elseif(in_array($action,['seen','unseen','move'],true)){gszMailRemoteAction($pdo,gszMailRemote($config),(int)$_SESSION['admin_id'],$id,$action,(string)($_POST['target']??''));$_SESSION['app_notice']=$action==='move'?'Verschiebung vom Server bestätigt; kein endgültiges Expunge ausgeführt.':'Gelesenstatus bestätigt.';}
 elseif($action==='classify'){$pdo->prepare('UPDATE mail_messages SET important=?,answered=? WHERE id=?')->execute([isset($_POST['important'])?1:0,isset($_POST['answered'])?1:0,$id]);gszAudit($pdo,(int)$_SESSION['admin_id'],'mail_classification',['message_id'=>$id]);}
 elseif($action==='assign'){$values=[];foreach(['property_id'=>'properties','customer_id'=>'customers','task_id'=>'tasks'] as $field=>$table){$value=(int)($_POST[$field]??0);if($value){$q=$pdo->prepare('SELECT id FROM '.$table.' WHERE id=?');$q->execute([$value]);if(!$q->fetchColumn())throw new InvalidArgumentException('Zuordnung nicht gefunden.');}$values[]=$value?:null;}$pdo->prepare('UPDATE mail_messages SET property_id=?,customer_id=?,task_id=? WHERE id=?')->execute([...$values,$id]);gszAudit($pdo,(int)$_SESSION['admin_id'],'mail_assignment',['message_id'=>$id]);}
 elseif($action==='rule'){$pattern=trim((string)($_POST['pattern']??''));if($pattern===''||mb_strlen($pattern)>190)throw new InvalidArgumentException('Absenderregel 1–190 Zeichen.');$pdo->prepare('INSERT INTO mail_rules(sender_pattern,important) VALUES(?,?)')->execute([$pattern,isset($_POST['important'])?1:0]);}
 elseif($action==='rule_toggle')$pdo->prepare('UPDATE mail_rules SET active=1-active WHERE id=?')->execute([(int)($_POST['rule_id']??0)]);
 else throw new InvalidArgumentException('Mailaktion unbekannt.');
 }catch(Throwable $e){gszUiError($e);}redirect($back);}
$folders=[];$messages=[];$detail=null;$attachments=[];$ready=true;$rules=[];$page=max(1,min(10000,(int)($_GET['page']??1)));$search=mb_substr(trim((string)($_GET['q']??'')),0,100);$total=0;
try{$folders=$pdo->query('SELECT * FROM mail_folders ORDER BY name')->fetchAll();$rules=$pdo->query('SELECT * FROM mail_rules ORDER BY id')->fetchAll();if($id){$detail=gszMailMessage($pdo,$id);$q=$pdo->prepare('SELECT * FROM mail_attachments WHERE message_id=? ORDER BY id');$q->execute([$id]);$attachments=$q->fetchAll();}else{$where=' FROM mail_messages m JOIN mail_folders f ON f.id=m.folder_id WHERE f.name=? AND m.active=1 AND (m.subject LIKE ? OR m.sender LIKE ? OR m.body LIKE ?)';$args=[$folder,'%'.$search.'%','%'.$search.'%','%'.$search.'%'];$q=$pdo->prepare('SELECT COUNT(*)'.$where);$q->execute($args);$total=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT m.*'.$where.' ORDER BY COALESCE(m.sent_at,m.created_at) DESC,m.id DESC LIMIT 30 OFFSET '.(($page-1)*30));$q->execute($args);$messages=$q->fetchAll();}}catch(Throwable $e){$ready=false;$_SESSION['app_error']='Mail-Datenmodell nicht bereit. Gesamtstand-Migration ausführen.';}
require_once dirname(__DIR__).'/private/mail_credentials.php';$blocked=gszMailAuthBlockedNow();$connected=filter_var($config['mail_enabled']??false,FILTER_VALIDATE_BOOLEAN)&&!empty($config['mail_pass']);
$when=static function(?string $utc):string{if(!$utc)return '';$d=(new DateTimeImmutable($utc.' UTC'))->setTimezone(new DateTimeZone('Europe/Berlin'));$today=new DateTimeImmutable('today',new DateTimeZone('Europe/Berlin'));return $d>=$today?$d->format('H:i'):($d>=$today->modify('-6 days')?['','Mo','Di','Mi','Do','Fr','Sa','So'][(int)$d->format('N')]:$d->format('d.m.'));};
$name=static fn(string $from)=>trim(preg_replace('/\s*<[^>]*>\s*/','',$from))?:$from;$folderLabel=static fn(string $f)=>$f==='INBOX'?'Posteingang':$f;
gszPageStart($detail?'Nachricht':'Mail');
if($blocked):?><a class="att" href="connections.php"><span>Das Postfach hat das Passwort abgelehnt. Bitte neu eintragen.</span></a><?php elseif(!$connected):?><a class="att" href="connections.php"><span>Postfach einrichten</span></a><?php endif?>
<?php if($ready&&$detail):?><p><a href="mail.php?folder=<?=e(rawurlencode($folder))?>">‹ <?=e($folderLabel($folder))?></a></p><section class="card"><h2><?=e($detail['subject'])?></h2><p class="muted"><?=e($detail['sender'])?> · <?=e($when($detail['sent_at']))?></p><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($detail['body'])?></div>
<?php foreach($attachments as $a):?><p><a href="mail_download.php?id=<?=(int)$a['id']?>">Anhang: <?=e($a['original_name'])?></a> <span class="muted">(<?=max(1,(int)round($a['size_bytes']/1024))?> KB)</span></p><?php endforeach?>
<div class="actions"><a class="btn primary" href="compose.php?message=<?=$id?>&amp;mode=reply">Antworten</a><a class="btn" href="compose.php?message=<?=$id?>&amp;mode=reply_all">Allen antworten</a><a class="btn" href="compose.php?message=<?=$id?>&amp;mode=forward">Weiterleiten</a></div></section>
<details class="card"><summary>Ablegen und markieren</summary><form method="post"><?php gszFields($detail['seen']?'unseen':'seen');?><button><?=$detail['seen']?'Als ungelesen markieren':'Als gelesen markieren'?></button></form><form method="post"><?php gszFields('move');?><label>In Ordner verschieben<select name="target"><?php foreach($folders as $f):?><option value="<?=e($f['name'])?>"><?=e($folderLabel($f['name']))?></option><?php endforeach?></select></label><button>Verschieben</button></form>
<form method="post"><?php gszFields('classify');?><label><input type="checkbox" name="important" <?=$detail['important']?'checked':''?>> Wichtig – erinnern, wenn nach einem Tag keine Antwort</label><label><input type="checkbox" name="answered" <?=$detail['answered']?'checked':''?>> Erledigt</label><button>Speichern</button></form>
<form method="post"><?php gszFields('assign');?><label>Objekt<select name="property_id"><option value="0">–</option><?php foreach($pdo->query('SELECT id,name FROM properties ORDER BY name LIMIT 500') as $o):?><option value="<?=(int)$o['id']?>" <?=(int)($detail['property_id']??0)===(int)$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach?></select></label><label>Kunde<select name="customer_id"><option value="0">–</option><?php foreach($pdo->query('SELECT id,name FROM customers ORDER BY name LIMIT 500') as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($detail['customer_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><input type="hidden" name="task_id" value="<?=(int)($detail['task_id']??0)?>"><button>Zuordnen</button></form></details>
<?php elseif($ready):?><div class="actions"><a class="btn primary" href="compose.php">Neue Mail</a><?php if($connected&&!$blocked):?><form method="post"><?php gszFields('sync');?><button>Abrufen</button></form><?php endif?></div>
<?php if(count($folders)>1):?><nav class="actions" aria-label="Ordner"><?php foreach($folders as $f):?><a href="mail.php?folder=<?=e(rawurlencode($f['name']))?>"<?=$f['name']===$folder?' aria-current="page"':''?>><?=e($folderLabel($f['name']))?></a><?php endforeach?></nav><?php endif?>
<form class="search" method="get" role="search"><input type="hidden" name="folder" value="<?=e($folder)?>"><label class="sr-only" for="mq">Mails durchsuchen</label><input id="mq" type="search" name="q" maxlength="100" value="<?=e($search)?>" placeholder="Mails durchsuchen"></form>
<?php if($messages):?><div class="list mail-list"><?php foreach($messages as $m):?><a class="mail-item<?=$m['seen']?'':' unread'?>" href="mail.php?folder=<?=e(rawurlencode($folder))?>&amp;id=<?=(int)$m['id']?>"><span class="name"><?=e($name((string)$m['sender']))?><span class="sub"><?=e($m['subject'])?></span></span><span class="muted"><?=e($when($m['sent_at']))?></span></a><?php endforeach?></div>
<?php else:?><div class="empty"><strong><?=$search!==''?'Keine passenden Mails.':'Keine Mails.'?></strong><?=$search!==''?'':($connected?'Mit „Abrufen“ neue Nachrichten holen.':'')?></div><?php endif?>
<nav class="actions"><?php if($page>1):?><a href="?folder=<?=e(rawurlencode($folder))?>&amp;q=<?=e(rawurlencode($search))?>&amp;page=<?=$page-1?>">Neuere</a><?php endif?><?php if($page*30<$total):?><a href="?folder=<?=e(rawurlencode($folder))?>&amp;q=<?=e(rawurlencode($search))?>&amp;page=<?=$page+1?>">Ältere</a><?php endif?></nav>
<details class="card"><summary>Erinnerungsregeln</summary><p class="hint">Mails von diesen Absendern werden als wichtig markiert. Wichtige Mails ohne Antwort erscheinen nach einem Tag auf der Startseite.</p><?php foreach($rules as $r):?><form method="post" class="actions"><?php gszFields('rule_toggle');?><input type="hidden" name="rule_id" value="<?=(int)$r['id']?>"><span style="flex:1"><?=e($r['sender_pattern'])?> <span class="muted">· <?=$r['active']?'aktiv':'pausiert'?></span></span><button class="small"><?=$r['active']?'Pausieren':'Aktivieren'?></button></form><?php endforeach?><form method="post"><?php gszFields('rule');?><label>Absender enthält<input name="pattern" maxlength="190" required></label><label><input type="checkbox" name="important" checked> Wichtig</label><button>Regel speichern</button></form></details><?php endif?><?php gszPageEnd(); ?>
